{
  "module": "tenants",
  "operations": [
    {
      "name": "tenants.add-user-to-tenant",
      "kind": "write",
      "description": "Add a user to an active tenant with a role. Allowed for a global administrator or a TenantOwner of the tenant; if the tenant has never had a member, any caller may add its first member with any role. A user who is already a member is rejected; use tenants.change-user-role to change an existing member\u0027s role."
    },
    {
      "name": "tenants.change-user-role",
      "kind": "write",
      "description": "Change the role of an existing member of an active tenant. Allowed for a global administrator or a TenantOwner of the tenant. A user who is not a member is rejected, and setting the role the member already has is accepted and changes nothing. Demoting the last TenantOwner is allowed; afterwards only a global administrator can manage the tenant\u0027s members, roles and configuration."
    },
    {
      "name": "tenants.create-tenant",
      "kind": "write",
      "description": "Create a new tenant with an identifier, a display name and a description (null for none). Only a global administrator can create tenants. The tenant starts active with no members and no configuration; an identifier that already exists is rejected."
    },
    {
      "name": "tenants.disable-tenant",
      "kind": "write",
      "description": "Disable an active tenant. Its data stays readable, but changes to its name, description, members, roles and configuration are rejected until it is enabled again. Only a global administrator can disable a tenant; disabling an unknown or already disabled tenant is rejected."
    },
    {
      "name": "tenants.enable-tenant",
      "kind": "write",
      "description": "Enable a disabled tenant so changes to its name, description, members, roles and configuration are accepted again. Only a global administrator can enable a tenant; enabling an unknown or already active tenant is rejected."
    },
    {
      "name": "tenants.remove-tenant-configuration",
      "kind": "write",
      "description": "Delete one configuration setting from an active tenant. Allowed for a global administrator or a TenantOwner of the tenant; removing a key the tenant does not have is rejected."
    },
    {
      "name": "tenants.remove-user-from-tenant",
      "kind": "write",
      "description": "Remove a user\u0027s membership from an active tenant, revoking the user\u0027s role in that tenant. Allowed for a global administrator or a TenantOwner of the tenant; removing a user who is not a member is rejected. Removing the last TenantOwner is allowed; afterwards only a global administrator can manage the tenant\u0027s members, roles and configuration."
    },
    {
      "name": "tenants.set-tenant-configuration",
      "kind": "write",
      "description": "Create or overwrite one configuration setting, a key with a string value, on an active tenant. Allowed for a global administrator or a TenantOwner of the tenant. A tenant holds at most 100 keys, so adding a new key beyond that is rejected while overwriting an existing key still works; setting a key to the value it already has changes nothing. Every tenant member can read the values, so do not store secrets."
    },
    {
      "name": "tenants.update-tenant",
      "kind": "write",
      "description": "Replace the display name and description of an existing active tenant. Allowed for a global administrator or a tenant member with the TenantOwner or TenantContributor role. Unknown or disabled tenants are rejected."
    }
  ]
}

